var numbers = [];
var C = 35;

while (C <= 65) {
  if (C % 3 == 0) {
    numbers.push(C + 1);
  }
  C++;
}

numbers.forEach((num) => {
  num *= 2;
});

console.log('Answer: ' + Math.max.apply(null, numbers));
```

